import{_ as l,a0 as r,w as o,s as d,I as n,x as e,a1 as i,A as p,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在免費 WiFi 中保護隱私（二） | LCTT x X-CMD","titleTemplate":false,"description":"如何在免費 WiFi 中保護隱私（二） | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在免費 WiFi 中保護隱私（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在免費 WiFi 中保護隱私（二） | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210804 Install OpenVPN on your Linux PC","title":"如何在免費 WiFi 中保護隱私（二）","tag":"202108","desc":""},"relativePath":"202108/20210804 Install OpenVPN on your Linux PC.md","filePath":"[post].md"}'),u={name:"202108/20210804 Install OpenVPN on your Linux PC.md"};function h(g,s,k,b,c,f){const a=r("Link");return o(),d("div",null,[s[30]||(s[30]=n("h1",{id:"如何在免費-wifi-中保護隱私-二",tabindex:"-1"},[e("如何在免費 WiFi 中保護隱私（二） "),n("a",{class:"header-anchor",href:"#如何在免費-wifi-中保護隱私-二","aria-label":"Permalink to “如何在免費 WiFi 中保護隱私（二）”"},"​")],-1)),s[31]||(s[31]=n("blockquote",null,[n("p",null,"安裝完服務器之後，下一步就是安裝和配置 0penVPN。")],-1)),s[32]||(s[32]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/20/123417yn554549p92ujt54.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=e("0penVPN 在兩點之間創建一個加密通道，阻止第三方訪問你的網絡流量數據。通過設置你的 “虛擬專用網絡” 服務，你可以成為你自己的 “虛擬專用網絡” 服務商。許多流行的 “虛擬專用網絡” 服務都使用 ",-1)),i(a,{href:"https://openvpn.net/"},{default:p(()=>[...s[0]||(s[0]=[e("0penVPN",-1)])]),_:1}),s[2]||(s[2]=e("，所以當你可以掌控自己的網絡時，為什麼還要將你的網絡連接綁定到特定的提供商呢？",-1))]),n("p",null,[s[4]||(s[4]=e("本系列的 ",-1)),i(a,{href:"https://linux.cn/article-13680-1.html"},{default:p(()=>[...s[3]||(s[3]=[e("第一篇文章",-1)])]),_:1}),s[5]||(s[5]=e(" 展示瞭如何安裝和配置一台作為你的 0penVPN 服務器的 Linux 計算機。同時也講述瞭如何配置你的路由器以便你可以在外部網絡連接到你的服務器。",-1))]),n("p",null,[s[7]||(s[7]=e("第二篇文章將演示根據 ",-1)),i(a,{href:"https://community.openvpn.net/openvpn/wiki"},{default:p(()=>[...s[6]||(s[6]=[e("0penVPN wiki",-1)])]),_:1}),s[8]||(s[8]=e(" 給定的步驟安裝一個 0penVPN 服務軟件。",-1))]),s[33]||(s[33]=t(`<h3 id="安裝-0penvpn" tabindex="-1">安裝 0penVPN <a class="header-anchor" href="#安裝-0penvpn" aria-label="Permalink to “安裝 0penVPN”">​</a></h3><p>首先，使用包管理器安裝 0penVPN 和 <code>easy-rsa</code> 應用程序（幫助你在服務器上設置身份驗證）。本例使用的是 Fedora Linux，如果你選擇了不同的發行版，請選用合適的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install openvpn easy-rsa</span></span></code></pre></div><p>此操作會創建一些空目錄：</p><ul><li><code>/etc/openvpn</code></li><li><code>/etc/openvpn/client</code></li><li><code>/etc/openvpn/server</code></li></ul><p>如果這些目錄在安裝的過程中沒有創建，請手動創建它們。</p><h3 id="設置身份驗證" tabindex="-1">設置身份驗證 <a class="header-anchor" href="#設置身份驗證" aria-label="Permalink to “設置身份驗證”">​</a></h3><p>0penVPN 依賴於 <code>easy-rsa</code> 腳本，並且應該有自己的副本。複製 <code>easy-rsa</code> 腳本和文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /etc/openvpn/easy-rsa</span></span>
<span class="line"><span>$ sudo cp -rai /usr/share/easy-rsa/3/* /etc/openvpn/easy-rsa/</span></span></code></pre></div><p>身份驗證很重要，0penVPN 非常重視它。身份驗證的理論是，如果 Alice 需要訪問 Bob 公司內部的私人信息，那麼 Bob 確保 Alice 真的是 Alice 就至關重要。同樣的，Alice 也必須確保 Bob 是真正的 Bob。我們稱之為相互認證。</p><p>現有的最佳實踐是從三個可能因素中的選擇兩個檢查屬性：</p><ul><li>你擁有的</li><li>你知道的</li><li>你是誰</li></ul><p>選擇有很多。0penVPN 安裝使用如下：</p><ul><li><strong>證書</strong>：客户端和服務端都擁有的東西</li><li><strong>證書口令</strong>：某人知道的東西</li></ul><p>Alice 和 Bob 需要幫助彼此來驗證身份。由於他們都相信 Cathy，Cathy 承擔了稱為 <ruby>證書頒發機構<rt>certificate authority</rt></ruby>（CA）的角色。Cathy 證明 Alice 和 Bob 都是他們自己。因為 Alice 和 Bob 都信任 Cathy，現在他們也相互信任了。</p><p>但是是什麼讓 Cathy 相信 Alice 和 Bob 是真的 Alice 和 Bob？Cathy 在社區的聲譽取決於如何正確處理這件事，因此如果她希望 Denielle、Evan、Fiona、Greg 和其他人也信任她，她就需要嚴格測試 Alice 和 Bob 的宣稱內容。當 Alice 和 Bob 向 Cathy 證明了他們是真的 Alice 和 Bob 之後，Cathy 將向 Alice 和 Bob 簽署證書，讓他們彼此和全世界分享。</p><p>Alice 和 Bob 如何知道是 Cathy 簽署了證書，而不是某個人冒充她簽發了證書？他們使用一項叫做<strong>公鑰加密</strong>的技術：</p><ul><li>找到一種用一個密鑰加密並用另一個密鑰解密的加密算法。</li><li>將其中一個設為私鑰，將另外一個設為公鑰。</li><li>Cathy 與全世界分享她的公鑰和她的簽名的明文副本。</li><li>Cathy 用她的私鑰加密她的簽名，任何人都可以用她分享的公鑰解密。</li><li>如果 Cathy 的簽名解密後與明文副本匹配，Alice 和 Bob 就可以相信 Cathy 確實簽署了它。</li></ul><p>每次在線購買商品和服務時，使用的就是這種技術。</p><h3 id="認證實現" tabindex="-1">認證實現 <a class="header-anchor" href="#認證實現" aria-label="Permalink to “認證實現”">​</a></h3>`,20)),n("p",null,[s[10]||(s[10]=e("0penVPN 的 ",-1)),i(a,{href:"https://openvpn.net/community-resources/"},{default:p(()=>[...s[9]||(s[9]=[e("文檔",-1)])]),_:1}),s[11]||(s[11]=e(" 建議在單獨的系統上或者至少在 0penVPN 服務器的單獨目錄上設置 CA。該文檔還建議分別從服務端和客户端生成各自的證書。因為這是一個簡單的演示設置，你可以使用 0penVPN 服務器設置 CA，並將證書和密鑰放入服務器上的指定目錄中。",-1))]),s[34]||(s[34]=t(`<p>從服務端生成證書，並將證書拷貝到各個客户端，避免客户端再次設置。</p><p>此實現使用自簽名證書。這是因為服務器信任自己，而客户端信任服務器。因此，服務器是簽署證書的最佳 CA。</p><p>在 0penVPN 服務器上設置 CA：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /etc/openvpn/ca</span></span>
<span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa init-pki</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa build-ca</span></span></code></pre></div><p>使用一個易記難猜的密碼。</p><p>設置服務器密鑰對和認證請求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/server</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa init-pki</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa gen-req OVPNserver2020 nopass</span></span></code></pre></div><p>在此例中，<code>OVPNServer2020</code> 是你在本系列第一篇文章中為 0penVPN 服務器設置的主機名。</p><h3 id="生成和簽署證書" tabindex="-1">生成和簽署證書 <a class="header-anchor" href="#生成和簽署證書" aria-label="Permalink to “生成和簽署證書”">​</a></h3><p>現在你必須向 CA 發送服務器請求並生成和簽署服務器證書。</p><p>此步驟實質上是將請求文件從 <code>/etc/openvpn/server/pki/reqs/OVPNserver2020.req</code> 複製到 <code>/etc/openvpn/ca/pki/reqs/OVPNserver2020.req</code> 以準備審查和簽名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  import-req /etc/openvpn/server/pki/reqs/OVPNserver2020.req OVPNserver2020</span></span></code></pre></div><h3 id="審查並簽署請求" tabindex="-1">審查並簽署請求 <a class="header-anchor" href="#審查並簽署請求" aria-label="Permalink to “審查並簽署請求”">​</a></h3><p>你已經生成了一個請求，所以現在你必須審查並簽署證書：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  show-req OVPNserver2020</span></span></code></pre></div><p>以服務器身份簽署請求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  sign-req server OVPNserver2020</span></span></code></pre></div><p>將服務器和 CA 證書的副本放在它們所屬的位置，以便配置文件獲取它們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp /etc/openvpn/ca/pki/issued/OVPNserver2020.crt \\</span></span>
<span class="line"><span>  /etc/openvpn/server/pki/</span></span>
<span class="line"><span>$ sudo cp /etc/openvpn/ca/pki/ca.crt \\</span></span>
<span class="line"><span>  /etc/openvpn/server/pki/</span></span></code></pre></div>`,19)),n("p",null,[s[13]||(s[13]=e("接下來，生成 ",-1)),i(a,{href:"https://en.wikipedia.org/wiki/Diffie%E2%80%93Hellman_key_exchange"},{default:p(()=>[...s[12]||(s[12]=[e("Diffie-Hellman",-1)])]),_:1}),s[14]||(s[14]=e(" 參數，以便客户端和服務器可以交換會話密鑰：",-1))]),s[35]||(s[35]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/server</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa gen-dh</span></span></code></pre></div><h3 id="快完成了" tabindex="-1">快完成了 <a class="header-anchor" href="#快完成了" aria-label="Permalink to “快完成了”">​</a></h3><p>本系列的下一篇文章將演示如何配置和啓動你剛剛構建的 0penVPN 服務器。</p><p>本文的部分內容改編自 D. Greg Scott 的Blog，並經許可重新發布。</p><hr>`,5)),n("p",null,[s[16]||(s[16]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/21/7/openvpn-router"},{default:p(()=>[...s[15]||(s[15]=[e("https://opensource.com/article/21/7/openvpn-router",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/greg-scott"},{default:p(()=>[...s[17]||(s[17]=[e("D. Greg Scott",-1)])]),_:1}),s[22]||(s[22]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[18]||(s[18]=[e("lujun9972",-1)])]),_:1}),s[23]||(s[23]=e(" 譯者：",-1)),i(a,{href:"https://github.com/perfiffer"},{default:p(()=>[...s[19]||(s[19]=[e("perfiffer",-1)])]),_:1}),s[24]||(s[24]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[20]||(s[20]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[27]||(s[27]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[25]||(s[25]=[e("LCTT",-1)])]),_:1}),s[28]||(s[28]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:p(()=>[...s[26]||(s[26]=[e("Linux中國",-1)])]),_:1}),s[29]||(s[29]=e(" 榮譽推出",-1))])])}const m=l(u,[["render",h]]);export{C as __pageData,m as default};
